function smartGenerationVersionKey(version){
    if(!version) return '';
    const id = String(version.id || '').trim();
    if(id) return `id:${id}`;
    const urls = (version.images || []).map(item => String(item?.url || '').trim()).filter(Boolean);
    return urls.length ? `media:${urls.join('|')}` : '';
}
async function reviewCanvasSyncConflicts(state){
    if(!state?.conflicts?.length || canvasSyncConflictDialogPromise) return;
    canvasSyncConflictDialogPromise = (async()=>{
        const details = state.conflicts.slice(0, 8).map(item => `• ${item.path}`).join('\n');
        const more = state.conflicts.length > 8 ? `\n… ${state.conflicts.length - 8} ${canvasSyncText('处冲突未展开','more conflicts')}` : '';
        if(window.StudioDialog?.alert){
            await window.StudioDialog.alert(
                canvasSyncText(`同一画布有并行修改，已保留本地草稿。冲突字段：\n${details}${more}`,
                    `This canvas has concurrent edits. The local draft was kept. Conflicting fields:\n${details}${more}`),
                {title:canvasSyncText('需要审阅画布冲突','Review canvas conflicts'), type:'warning'}
            );
        }
        const keepLocal = window.StudioDialog?.confirm
            ? await window.StudioDialog.confirm(
                canvasSyncText('确定保留本地草稿并尝试保存吗？选择“取消”将采用远端版本，但本地草稿仍保存在本机。',
                    'Keep the local draft and try saving it? Choose “Cancel” to use the remote version; the local draft remains on this device.'),
                {title:canvasSyncText('选择保留版本','Choose a version'), type:'warning'}
            )
            : true;
        if(canvasSyncConflictState !== state) return;
        canvasSyncRetryBase = state.remote;
        canvasSyncSaveBlocked = true;
        if(keepLocal){
            canvasSyncApplySnapshot(state.merged.canvas);
            canvasSyncConflictState = null;
            canvasSyncSaveBlocked = false;
            scheduleSave();
        } else {
            canvasSyncApplySnapshot(state.remote);
            canvasSyncConflictState = null;
            canvasSyncSaveQueued = false;
            canvasSyncSaveBlocked = false;
        }
    })().catch(error => {
        canvasSyncReportError(error?.message || canvasSyncText('冲突审阅失败','Conflict review failed'));
    }).finally(()=>{ canvasSyncConflictDialogPromise = null; });
    await canvasSyncConflictDialogPromise;
}
function applyMergedServerCanvas(serverCanvas, options={}){
    if(!serverCanvas || !canvas) return null;
    const remote = canvasSyncIncomingSnapshot(serverCanvas);
    const local = options.localSnapshot || canvasSyncCurrentSnapshot() || remote;
    const base = options.base || canvasSyncRetryBase || canvasSyncBase || local;
    const merged = CANVAS_SYNC.merge(base, local, remote);
    const hadLocalChanges = canvasSyncHasLocalChanges(local, base);
    canvasSyncRetryBase = remote;
    canvasSyncSaveBlocked = Boolean(merged.conflicts.length);
    if(merged.conflicts.length){
        canvasSyncConflictState = {base, local, remote, merged, conflicts:merged.conflicts};
        canvasSyncStoreDraft(local, merged.conflicts, remote);
    } else {
        canvasSyncConflictState = null;
    }
    canvasSyncApplySnapshot(merged.canvas);
    if(merged.conflicts.length && options.prompt !== false) void reviewCanvasSyncConflicts(canvasSyncConflictState);
    if(!merged.conflicts.length && options.scheduleSave && hadLocalChanges) scheduleSave();
    return {...merged, base, local, remote, hadLocalChanges};
}
async function mergeReloadCanvasNow(){
    if(!canvasId) return;
    if(dragState || selectionState){
        // 用户正在拖拽/框选，稍后再合并，别打断操作
        scheduleCanvasMergeReload(600);
        return;
    }
    try {
        const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}`);
        if(!res.ok) return;
        const data = await res.json();
        if(data && data.canvas) applyMergedServerCanvas(data.canvas, {prompt:true, scheduleSave:true});
    } catch(e) {
        canvasSyncReportError(e?.message || canvasSyncText('读取远端画布失败','Failed to read the remote canvas'));
    }
}
function scheduleCanvasMergeReload(delay=200){
    clearTimeout(canvasSyncTimer);
    canvasSyncTimer = setTimeout(() => { mergeReloadCanvasNow(); }, delay);
}
function handleCanvasUpdatedMessage(data={}){
    if(!data || data.type !== 'canvas_updated') return;
    if(!canvasId || data.canvas_id !== canvasId) return;
    if(data.client_id && data.client_id === smartClientId) return; // 自己发的，忽略
    if(canvasSyncInFlight) return; // 我正在保存，保存完成/409 合并会处理
    const remoteRevision = Number(data.revision || 0);
    const remoteUpdatedAt = Number(data.updated_at || 0);
    if((remoteRevision && remoteRevision <= Number(canvas?.revision || 0)) || (!remoteRevision && remoteUpdatedAt && remoteUpdatedAt <= Number(canvas?.updated_at || 0))) return;
    scheduleCanvasMergeReload(200);
}
function startCanvasMetaPoll(){
    // WS / iframe 转发不可靠时的兜底：定期看服务器 updated_at 是否变新，变新就合并拉取
    if(canvasMetaPollTimer) return;
    canvasMetaPollTimer = setInterval(async () => {
        if(!canvasId || !canvas) return;
        if(canvasSyncInFlight || dragState || selectionState) return;
        try {
            const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}/meta`);
            if(!res.ok) return;
            const meta = await res.json();
            const remoteRevision = Number(meta.revision || 0);
            const remoteUpdatedAt = Number(meta.updated_at || 0);
            if((remoteRevision && remoteRevision > Number(canvas.revision || 0)) || (!remoteRevision && remoteUpdatedAt > Number(canvas.updated_at || 0))) mergeReloadCanvasNow();
        } catch(e) {}
    }, 8000);
}
function connectAssetLibrarySyncSocket(){
    if(window.parent && window.parent !== window) return;
    const host = window.location.host;
    if(!host) return;
    const protocol = location.protocol === 'https:' ? 'wss' : 'ws';
    const clientId = smartClientId;
    let socket;
    let retryTimer = null;
    const connect = () => {
        try {
            socket = new WebSocket(`${protocol}://${host}/ws/stats?client_id=${clientId}`);
        } catch(e) {
            retryTimer = setTimeout(connect, 3000);
            return;
        }
        socket.onmessage = event => {
            try {
                const data = JSON.parse(event.data);
                if(data?.type === 'asset_library_updated') handleAssetLibraryUpdatedMessage(data);
                if(data?.type === 'canvas_updated') handleCanvasUpdatedMessage(data);
            } catch(e) {}
        };
        socket.onclose = () => {
            retryTimer = setTimeout(connect, 3000);
        };
        socket.onerror = () => {
            try { socket.close(); } catch(e) {}
        };
    };
    window.addEventListener('beforeunload', () => {
        clearTimeout(retryTimer);
        try { socket?.close(); } catch(e) {}
    });
    connect();
}
function setAssetLibraryFromResponse(data, options={}){
    assetLibrary = data.library || assetLibrary;
    assetLibraryUpdatedAt = Number(assetLibrary.updated_at || assetLibraryUpdatedAt || 0);
    const libs = assetLibraries();
    if(!activeAssetLibraryId) activeAssetLibraryId = assetLibrary.active_library_id || libs[0]?.id || '';
    if(activeAssetLibraryId && activeAssetLibraryId !== LOCAL_ASSET_LIBRARY_ID && !libs.some(lib => lib.id === activeAssetLibraryId)) activeAssetLibraryId = libs[0]?.id || '';
    const cats = assetCategories('image');
    if(activeAssetCategoryId && !cats.some(cat => cat.id === activeAssetCategoryId)) activeAssetCategoryId = '';
    if(!activeAssetCategoryId) activeAssetCategoryId = activeAssetCategory()?.id || '';
    const workflowLibs = workflowAssetLibraries();
    if(activeWorkflowAssetLibraryId && !workflowLibs.some(lib => lib.id === activeWorkflowAssetLibraryId)) activeWorkflowAssetLibraryId = '';
    if(!activeWorkflowAssetLibraryId) activeWorkflowAssetLibraryId = workflowLibs[0]?.id || '';
    const workflowCats = workflowAssetCategories();
    if(activeWorkflowAssetCategoryId && !workflowCats.some(cat => cat.id === activeWorkflowAssetCategoryId)) activeWorkflowAssetCategoryId = '';
    if(!activeWorkflowAssetCategoryId) activeWorkflowAssetCategoryId = activeWorkflowAssetCategory()?.id || '';
    if(mentionAssetCategoryId && !cats.some(cat => cat.id === mentionAssetCategoryId)) mentionAssetCategoryId = '';
    if(!mentionAssetCategoryId) mentionAssetCategoryId = activeAssetCategoryId;
    if(options.render !== false) {
        renderAssetLibrary();
        if(mentionPicker?.classList?.contains('open') && mentionSource === 'asset') renderMentionPicker('asset');
    }
}
