function migrateSmartGroupImageMembers(){
    let changed = false;
    nodes.filter(isSmartGroupNode).forEach(group => {
        const legacyImages = (group.images || []).filter(item => item?.url);
        if(!legacyImages.length) return;
        const layout = smartGroupLayoutSize(group);
        const startX = Number(group.x || 0) + SMART_GROUP_ARRANGE_PADDING;
        const startY = Number(group.y || 0) + SMART_GROUP_ARRANGE_HEADER + SMART_GROUP_ARRANGE_PADDING;
        const memberIds = [];
        legacyImages.forEach((image, index) => {
            const row = Math.floor(index / 3);
            const col = index % 3;
            const member = {
                id:uid('material'),
                type:SMART_NODE_TYPES.material,
                sourceKind:'input',
                x:startX + col * 116,
                y:startY + row * 116,
                title:image.name || '素材',
                images:[stripImageGenerationMeta({...image})],
                scale:1,
                created_at:group.created_at || Date.now()
            };
            appendSmartNodes(member);
            memberIds.push(member.id);
        });
        group.items = Array.from(new Set([...(group.items || []), ...memberIds]));
        group.images = [];
        group.w = Math.max(layout.width, 340);
        group.h = Math.max(layout.height, 220);
        fitSmartGroupBounds(group);
        changed = true;
    });
    return changed;
}
async function restoreCanvasRuns(){
    if(!canvasId || !nodes.length) return [];
    let runs = [];
    try {
        const response = await fetch(`/api/canvas-runs?canvas_id=${encodeURIComponent(canvasId)}`);
        if(!response.ok) return [];
        const payload = await response.json();
        runs = Array.isArray(payload.runs) ? payload.runs : [];
    } catch(error) {
        return [];
    }
    const runById = new Map(runs.map(run => [String(run?.run_id || ''), run]).filter(entry => entry[0]));
    let restoredGenerationMetadata = false;
    const restoreGenerationReferences = target => {
        const run = runById.get(canvasRunId(target));
        if(!run || smartGenerationSnapshotRefs(target).length) return;
        const refs = smartRunRecordedReferences(run);
        if(!refs.length) return;
        target.runInputRefs = cloneSmartSettings(refs);
        target.runPromptRefs = cloneSmartSettings(refs);
        restoredGenerationMetadata = true;
    };
    [...nodes, ...CanvasCreation.tasks(nodes)].forEach(node => {
        const run = runById.get(canvasRunId(node));
        if(!run) return;
        restoreGenerationReferences(node);
        (node.resultVersions || []).forEach(restoreGenerationReferences);
        const attempt = (run.attempts || []).slice(-1)[0] || {};
        const status = String(attempt.status || 'validated');
        node.runStatus = status;
        node.runRef = {
            ...(node.runRef || {}),
            runId:String(run.run_id || ''),
            attemptId:String(attempt.attempt_id || node.runRef?.attemptId || ''),
            idempotencyKey:String(attempt.idempotency_key || node.runRef?.idempotencyKey || ''),
            providerTaskId:String(attempt.provider_task_id || ''),
            resultIds:Array.isArray(attempt.result_ids) ? attempt.result_ids.filter(Boolean) : [],
            syncError:''
        };
        if(['queued','submitted','processing'].includes(status)){
            node.running = status === 'processing';
            node.queued = status !== 'processing';
            if(!node.pending && smartPendingTasks(node).length) node.pending = smartPendingTasks(node).length;
        } else if(status === 'recoverable'){
            node.running = false;
            node.queued = false;
            node.runError = String(attempt.error || '任务可继续查询');
        } else if(status === 'failed'){
            node.running = false;
            node.queued = false;
            node.runError = String(attempt.error || '任务未完成');
        } else if(status === 'cancelled'){
            node.running = false;
            node.queued = false;
            delete node.runError;
        } else if(['succeeded','partially_succeeded'].includes(status)){
            node.running = false;
            node.queued = false;
            delete node.runError;
        }
    });
    if(restoredGenerationMetadata) scheduleSave();
    return runs;
}
function smartRunRecordedReferences(run){
    const inputs = run?.standard_request?.inputs || {};
    const keys = [
        ['reference','image'], ['references','image'], ['image','image'], ['images','image'],
        ['source_image','image'], ['first_frame','image'], ['last_frame','image'],
        ['video','video'], ['videos','video'], ['source_video','video'], ['reference_video','video'],
        ['audio','audio'], ['audios','audio'], ['source_audio','audio'], ['reference_audio','audio']
    ];
    const knownMedia = new Map();
    nodes.forEach(node => (node.images || []).forEach(item => {
        if(item?.url && !knownMedia.has(item.url)) knownMedia.set(item.url, item);
    }));
    const result = [];
    const seen = new Set();
    keys.forEach(([key, kind]) => {
        const raw = inputs[key];
        const values = Array.isArray(raw) ? raw : raw ? [raw] : [];
        values.forEach(value => {
            const candidate = value && typeof value === 'object' ? value : {url:String(value || '')};
            const url = String(candidate.url || candidate.path || candidate.uri || '').trim();
            const text = SMART_NODE_CONTRACT.textContentForMediaItem(candidate);
            if((!url && !text) || seen.has(`${kind}|${url}|${text}`)) return;
            seen.add(`${kind}|${url}|${text}`);
            const known = knownMedia.get(url) || {};
            result.push(normalizeSmartMediaReference({
                ...known,
                ...candidate,
                url,
                kind:candidate.kind || known.kind || kind,
                name:candidate.name || known.name || inputThumbLabel(kind, result.length + 1)
            }, result.length));
        });
    });
    return result.filter(hasMentionReferenceContent);
}
async function loadCanvas(){
    if(!canvasId) return;
    try {
        const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}`);
        if(!res.ok) return;
        const data = await res.json();
        canvas = canvasSyncIncomingSnapshot(data.canvas);
        canvasSyncRememberBase(canvas);
        rememberCanvasListProject(canvas.project || 'default');
        canvasUsesConnections = Object.prototype.hasOwnProperty.call(canvas || {}, 'connections');
        document.title = canvasDocumentTitle();
        document.getElementById('smartTitle').textContent = canvas.title || tr('canvas.smartCanvas');
    const legacyMigration = SMART_NODE_CONTRACT.migrateLegacyCanvas(canvas.nodes, canvas.connections);
    const migration = CanvasCreation.migrate(legacyMigration.nodes, legacyMigration.connections);
    nodes = migration.nodes.map(normalizeLegacySmartNode).filter(Boolean);
    const hydratedTextResults = await hydrateTextResultMediaContent(nodes);
    const migratedMusicNodes = migrateLegacyMusicGeneratorNodes();
        canvas.connections = migration.connections;
        smartNodeMigrationPending = Number(canvas.node_schema_version || 0) < SMART_NODE_SCHEMA_VERSION;
        migrateSmartGroupImageMembers();
        canvas.connections = Array.isArray(canvas.connections) ? canvas.connections : [];
        const numberedCanvas = CANVAS_SYNC.assignDisplayNumbers({...canvas, nodes});
        nodes = numberedCanvas.nodes;
        canvas.nextNodeNumber = numberedCanvas.nextNodeNumber;
        nodes.forEach(n => {
            if(isSmartDirectorNode(n)) n.timelinePlaying = false;
            const pendingTasks = smartPendingTasks(n);
            if(pendingTasks.length){
                n.pending = Math.max(pendingTasks.length, Number(n.pending || 0) || pendingTasks.length);
                n.running = false;
            } else if(smartNodeHasDisplayResult(n)){
                markSmartNodeComplete(n, {hideTimer:true});
            } else if(n.pending || n.queued){
                clearSmartNodeBusyState(n);
            }
        });
        const cleanedCompletedState = clearCompletedNodeBusyStates();
        const recoveredLoopOutputs = recoverStuckLoopOutputsFromLogs();
        const hiddenCompletedTimers = hideCompletedRunTimers();
        const cleanedDetachedInputs = cleanupDetachedRunInputRefs();
        viewport = {...viewport, ...(canvas.viewport || {})};
        viewport.scale = safeScale(viewport.scale);
        if(canvas.settings) settings = {...settings, ...canvas.settings};
        normalizeSmartVideoModeSettings(settings, true);
        nodes.forEach(node => {
            if(node.runSettings) normalizeSmartVideoModeSettings(node.runSettings, true);
        });
        const initializedRunningHubRegions = nodes.reduce((changed, node) => {
            if(node?.type !== SMART_NODE_TYPES.aiApp || !node.runSettings) return changed;
            const before = String(node.runSettings.rhRegion || '');
            const ref = selectedRunningHubRef(node.runSettings);
            return Boolean(ref && before !== String(node.runSettings.rhRegion || '')) || changed;
        }, false);
        const initializedExecutionDefaults = nodes.reduce((changed, node) => {
            if(!node.runSettings) return changed;
            return ensureExecutionSelectionDefaults(node.runSettings, node) || changed;
        }, false);
        canvasDefaultSmartSettings = cloneSmartSettings(settings);
        loadRecentSmartSettings();
        if(settings.comfy_workflow && !settings.comfyWorkflow) settings.comfyWorkflow = settings.comfy_workflow;
        if(settings.comfy_params && !settings.comfyParams) settings.comfyParams = settings.comfy_params;
        updateProviderModels();
        await restoreCanvasRuns();
        nodes.forEach(node => {
            const snapshot = manualExecutionSettingsSnapshot(node, node.runSettings || {});
            if(snapshot) manualNodeSettingsFingerprints.set(node.id, JSON.stringify(snapshot));
        });
        applyViewport();
        render();
    if(smartNodeMigrationPending || migratedMusicNodes || initializedRunningHubRegions || initializedExecutionDefaults || cleanedDetachedInputs || cleanedCompletedState || recoveredLoopOutputs || hiddenCompletedTimers || hydratedTextResults) scheduleSave();
        resumeSmartPendingTasks();
        resumeJimengPendingNodes();
        startCanvasMetaPoll();
        window.dispatchEvent(new Event('canvas-ready'));
    } catch(e) { toast(tr('smart.toastCanvasFail')); }
}
function migrateLegacyMusicGeneratorNodes(){
    let changed = false;
    nodes.forEach(node => {
        if(node?.type !== SMART_NODE_TYPES.audioGenerator) return;
        const runSettings = node.runSettings || {};
        const profile = capabilityProfileFor(runSettings.audioProvider, runSettings.audioModel, 'music_generation', capabilityRegionForProvider(runSettings.audioProvider, runSettings));
        if(profile?.node_type !== 'music_generation') return;
        node.type = SMART_NODE_TYPES.musicGenerator;
        node.title = SMART_NODE_CONTRACT.titleForType(node.type);
        node.outputKind = SMART_NODE_CONTRACT.outputKindForType(node.type);
        node.runSettings = SMART_NODE_CONTRACT.normalizeExecutionSettings(node, {
            ...runSettings,
            musicProvider:runSettings.musicProvider || runSettings.audioProvider || '',
            musicFamilyId:runSettings.musicFamilyId || runSettings.audioFamilyId || profile.family_id || '',
            musicModel:runSettings.musicModel || runSettings.audioModel || profile.model_id || ''
        });
        changed = true;
    });
    return changed;
}
function scheduleSave(){
    if(canvasSyncSaveBlocked) return;
    CanvasCreation.reconcile(nodes, undefined, canvas?.connections || []);
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveCanvas, 450);
}
function syncServerMediaUrls(serverNodes){
    if(!Array.isArray(serverNodes)) return false;
    const remoteById = new Map(serverNodes.filter(node => node?.id).map(node => [node.id, node]));
    let changed = false;
    nodes.forEach(node => {
        const remote = remoteById.get(node?.id);
        if(!remote || !Array.isArray(remote.images) || !Array.isArray(node.images)) return;
        remote.images.forEach((image, index) => {
            const current = node.images[index];
            const remoteUrl = String(image?.url || '').trim();
            if(!current || !remoteUrl || remoteUrl === String(current.url || '')) return;
            node.images[index] = {...current, ...image, url:remoteUrl};
            changed = true;
        });
    });
    return changed;
}
function syncServerNodeNumbers(serverNodes){
    if(!Array.isArray(serverNodes)) return false;
    const remoteById = new Map(serverNodes.filter(node => node?.id).map(node => [node.id, node]));
    let changed = false;
    nodes.forEach(node => {
        const remote = remoteById.get(node?.id);
        const number = canvasNodeDisplayNumber(remote?.displayNumber);
        if(!remote || !number || node.displayNumber === number) return;
        node.displayNumber = number;
        changed = true;
    });
    return changed;
}
async function saveCanvas(options={}){
    if(!canvasId || !canvas || canvasSyncSaveBlocked) return false;
    if(canvasSyncInFlight){ canvasSyncSaveQueued = true; return false; }
    savePromptDraftForCurrent();
    const storageCanvas = canvasSyncCurrentSnapshot();
    if(!storageCanvas) return false;
    const base = canvasSyncRetryBase || canvasSyncBase || storageCanvas;
    storageCanvas.revision = Number(base.revision || storageCanvas.revision || canvas.revision || 0);
    storageCanvas.updated_at = Number(base.updated_at || storageCanvas.updated_at || canvas.updated_at || 0);
    const retryCount = Math.max(0, Number(options.retryCount) || 0);
    canvasSyncSaveQueued = false;
    canvasSyncInFlight = true;
    try {
        const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}`, {
            method:'PUT',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({
                title:storageCanvas.title || tr('smart.title'),
                icon:storageCanvas.icon || 'sparkles',
                nodes:storageCanvas.nodes || [],
                connections:canvasSyncNormalizeConnections(storageCanvas.connections),
                viewport:storageCanvas.viewport || {x:0,y:0,scale:1},
                logs:storageCanvas.logs || [],
                settings:storageCanvas.settings,
                base_updated_at:storageCanvas.updated_at,
                base_revision:storageCanvas.revision,
                client_id:smartClientId,
                migration_version:smartNodeMigrationPending ? SMART_NODE_SCHEMA_VERSION : 0
            })
        });
        if(res.ok){
            const data = await res.json().catch(() => ({}));
            const savedCanvas = canvasSyncIncomingSnapshot(data.canvas || storageCanvas);
            if(syncServerMediaUrls(data.canvas?.nodes) || syncServerNodeNumbers(data.canvas?.nodes)){
                canvas.nodes = nodes;
                render();
                scheduleConnectionLayerRefresh();
            }
            if(data.canvas && data.canvas.updated_at) canvas.updated_at = data.canvas.updated_at;
            canvas.revision = Number(data.canvas?.revision || canvas.revision || 1);
            canvas.updated_at = Number(savedCanvas.updated_at || canvas.updated_at || 0);
            canvas.nextNodeNumber = Number(savedCanvas.nextNodeNumber || canvas.nextNodeNumber || 1);
            canvasSyncRememberBase(savedCanvas);
            canvasSyncSaveBlocked = false;
            canvasSyncConflictState = null;
            canvasSyncClearDraft();
            if(smartNodeMigrationPending){
                const migrationConfirmed = Number(data.canvas?.node_schema_version || 0) >= SMART_NODE_SCHEMA_VERSION;
                if(migrationConfirmed){
                    canvas.node_schema_version = Number(data.canvas.node_schema_version);
                    smartNodeMigrationPending = false;
                    smartMigrationRestartNotified = false;
                } else if(!smartMigrationRestartNotified){
                    smartMigrationRestartNotified = true;
                    toast(tr('smart.toastMigrationRestart'));
                }
            }
            return true;
        }
        const data = await res.json().catch(() => ({}));
        if(res.status === 409){
            const serverCanvas = data.detail?.canvas;
            if(serverCanvas){
                canvas.revision = Math.max(1, Number(serverCanvas.revision || canvas.revision || 1));
                const merged = applyMergedServerCanvas(serverCanvas, {base, localSnapshot:canvasSyncCurrentSnapshot(), prompt:true});
                if(merged?.conflicts?.length) return false;
                if(retryCount < 1){
                    clearTimeout(saveTimer);
                    saveTimer = setTimeout(() => saveCanvas({retryCount:retryCount + 1}), 300);
                } else {
                    canvasSyncReportError(canvasSyncText('远端版本再次变化，请稍后重试','The remote version changed again; please retry shortly'));
                }
            } else {
                canvasSyncReportError(apiErrorMessage(data, canvasSyncText('画布冲突响应缺少远端内容','Canvas conflict response has no remote content')));
            }
            return false;
        }
        canvasSyncReportError(apiErrorMessage(data, canvasSyncText(`服务器返回 ${res.status}` , `Server returned ${res.status}`)));
        return false;
    } catch(e) {
        canvasSyncReportError(e?.message || canvasSyncText('网络错误','Network error'));
        return false;
    } finally {
        canvasSyncInFlight = false;
        if(canvasSyncSaveQueued && !canvasSyncSaveBlocked){
            canvasSyncSaveQueued = false;
            scheduleSave();
        }
    }
}
