    const entry = {
        id:uid('log'),
        createdAt:Date.now(),
        status:'failed',
        platform:meta?.provider || capabilityUiText('画布','Canvas'),
        nodeId,
        nodeType:node?.type || 'canvas-notice',
        model:meta?.model || '',
        request:{source:'ui', kind:'validation'},
        prompt:String(node?.promptDraftText || ''),
        outputs:[],
        refs:[],
        runMs:0,
        error:message
    };
