async function comfyNameForRef(ref){
    const localRef = String(ref?.url || '').startsWith('/assets/');
    if(ref.comfy_name && !localRef) return ref.comfy_name;
    const response = await fetch(ref.url);
    if(!response.ok) throw new Error(`无法读取参考素材「${ref.name || ref.url}」（HTTP ${response.status}）`);
    const blob = await response.blob();
    const form = new FormData();
    form.append('files', blob, ref.name || 'smart-ref.png');
    const data = await fetch('/api/upload', {method:'POST', body:form}).then(async r => {
        if(!r.ok) throw new Error(await r.text());
        return r.json();
    });
    const name = String(data.files?.[0]?.comfy_name || '').trim();
    if(!name) throw new Error(`参考素材「${ref.name || ref.url}」上传到 ComfyUI 失败`);
    const node = ref.nodeId ? nodes.find(n => n.id === ref.nodeId) : null;
    const image = node?.images?.find(img => img.url === ref.url) || (nodes || []).flatMap(n => n.images || []).find(img => img?.url === ref.url);
    if(image) image.comfy_name = name;
    ref.comfy_name = name;
    return name;
}
function smartMinimaxPrompt(node, selectedOverride=null){
    const seg = selectedOverride || smartMinimaxSelectedSegment(node);
    const prompt = String(seg?.prompt || '').trim() || String(node.promptDraftText || '').trim() || inputPromptTextFor(node) || '';
    if(!isMiniMaxDirectorNode(node)) return prompt;
    return prompt || 'Generate a cinematic video clip.';
}
async function smartMinimaxDynamicParams(node, selectedOverride=null){
    const seg = selectedOverride || smartMinimaxSelectedSegment(node);
    const duration = Math.max(0.5, Number(seg?.duration || node.duration || 8) || 8);
    const params = {
        "136":{},
        "115":{aspect_ratio:seg?.aspectRatio || node.aspectRatio || '16:9 (Widescreen)', megapixels:Number(seg?.megapixels || node.megapixels || 0.4)},
        "132":{value:duration},
        "138":{value:smartMinimaxPrompt(node, seg)},
        "129":{noise_seed:Math.floor(Math.random() * 4294967295)}
    };
    for(let i = 0; i < SMART_MINIMAX_REF_IMAGE_MAX; i++) params["136"][`ref_images.ref_image_${i}`] = null;
    for(let i = 0; i < SMART_MINIMAX_REF_VIDEO_MAX; i++) params["136"][`ref_videos.ref_video_${i}`] = null;
    for(let i = 0; i < SMART_MINIMAX_REF_AUDIO_MAX; i++) params["136"][`ref_audios.ref_audio_${i}`] = null;
    const images = smartMinimaxRefsForKind(node, 'image', seg);
    if(images.length > SMART_MINIMAX_REF_IMAGE_MAX) throw new Error(`MiniMax H3 最多支持 ${SMART_MINIMAX_REF_IMAGE_MAX} 张参考图`);
    for(let i = 0; i < images.length; i++){
        const name = await comfyNameForRef(images[i]);
        params[String(9000 + i)] = {class_type:'LoadImage', inputs:{image:name}, _meta:{title:`MiniMax image ${i + 1}`}};
        params["136"][`ref_images.ref_image_${i}`] = [String(9000 + i), 0];
    }
    const videos = smartMinimaxRefsForKind(node, 'video', seg);
    if(videos.length > SMART_MINIMAX_REF_VIDEO_MAX) throw new Error(`MiniMax H3 最多支持 ${SMART_MINIMAX_REF_VIDEO_MAX} 段参考视频`);
    for(let i = 0; i < videos.length; i++){
        const name = await comfyNameForRef(videos[i]);
        const loadNodeId = String(9040 + i);
        const componentsNodeId = String(9050 + i);
        params[loadNodeId] = {class_type:'LoadVideo', inputs:{file:name}, _meta:{title:`MiniMax video ${i + 1}`}};
        params[componentsNodeId] = {class_type:'GetVideoComponents', inputs:{video:[loadNodeId, 0]}, _meta:{title:`MiniMax video frames ${i + 1}`}};
        params["136"][`ref_videos.ref_video_${i}`] = [componentsNodeId, 0];
    }
    const audios = smartMinimaxRefsForKind(node, 'audio', seg);
    if(audios.length > SMART_MINIMAX_REF_AUDIO_MAX) throw new Error(`MiniMax H3 最多支持 ${SMART_MINIMAX_REF_AUDIO_MAX} 段参考音频`);
    for(let i = 0; i < audios.length; i++){
        const name = await comfyNameForRef(audios[i]);
        params[String(9060 + i)] = {class_type:'LoadAudio', inputs:{audio:name}, _meta:{title:`MiniMax audio ${i + 1}`}};
        params["136"][`ref_audios.ref_audio_${i}`] = [String(9060 + i), 0];
    }
    return params;
}
function smartMinimaxReadableError(error, engine='comfyui'){
    const text = String(error?.message || error || tr('smart.errRunFailed')).trim();
    const jsonStart = text.indexOf('{');
    if(jsonStart < 0) return text;
    try {
        const payload = JSON.parse(text.slice(jsonStart));
        const parts = [];
        const mainError = payload?.error;
        if(mainError?.message) parts.push(String(mainError.message));
        if(mainError?.details && !parts.includes(String(mainError.details))) parts.push(String(mainError.details));
        Object.entries(payload?.node_errors || {}).slice(0, 3).forEach(([nodeId, nodeError]) => {
            const details = (nodeError?.errors || []).slice(0, 2).map(item => item?.details || item?.message).filter(Boolean);
            if(details.length) parts.push(`节点 ${nodeId}${nodeError?.class_type ? `（${nodeError.class_type}）` : ''}：${details.join('；')}`);
        });
        const prefix = engine === 'runninghub'
            ? 'RunningHub 工作流执行失败'
            : engine === 'api'
                ? capabilityUiText('视频模型执行失败','Video model execution failed')
                : 'ComfyUI 拒绝了工作流';
        return parts.length ? `${prefix}：${parts.join('；')}` : text;
    } catch {
        return text;
    }
}
async function smartMinimaxRunningHubSettings(node){
    const entry = smartMinimaxRunningHubEntry(node);
    const workflowId = runningHubEntryId(entry, 'workflow');
    if(!entry || !workflowId) throw new Error(`请先在 API 设置中添加「${SMART_MINIMAX_RUNNINGHUB_WORKFLOW_TITLE}」`);
    const sourceSettings = {rhRegion:entry.region || node?.minimaxRunningHubRegion || settings.rhRegion};
    const cached = await ensureRunningHubWorkflow(workflowId, {fetchRemote:true}, sourceSettings).catch(() => null);
    const fields = smartMinimaxRunningHubFieldsForConfig(
        Array.isArray(cached?.fields) && cached.fields.length ? cached.fields : rhEntryFields(entry)
    );
    if(!fields.length) throw new Error(`请先在 API 设置中打开「${runningHubEntryLabel(entry, 'workflow')}」，拉取并保存工作流参数`);
    const workflowJson = rhWorkflowJsonFromSources(cached?.workflowJson, entry?.workflowJson, entry?.raw?.workflowJson, entry?.raw?.prompt);
    return {
        engine:'runninghub',
        rhConfigKey:runningHubEntryKey('workflow', workflowId),
        rhRegion:runningHubRegion(sourceSettings),
        rhPayment:'free',
        rhInstanceType:'',
        rhParams:{},
        rhRandomActive:{},
        rhFields:fields,
        rhWorkflowJson:workflowJson,
        rhOptionalImageMode:'prune-workflow'
    };
}
function smartMinimaxAspectForRunningHub(value, field=null){
    const text = String(value || '').trim();
    const match = text.match(/\d+\s*:\s*\d+/);
    const ratio = match ? match[0].replace(/\s+/g, '') : '16:9';
    if(smartMinimaxRunningHubFullAspectField(field)) return smartMinimaxFullAspectLabel(ratio);
    const defaultValue = rhDefaultValue(field);
    if(defaultValue && new RegExp(`^${ratio.replace(':', '\\s*:\\s*')}(?:\\s|$)`).test(defaultValue.replace(/\s+/g, ' '))) return defaultValue;
    const options = rhExtractFieldOptions(field) || [];
    const option = options.find(item => String(item).replace(/\s+/g, '').startsWith(ratio));
    return option || ratio;
}
function smartMinimaxRunRefs(node, selectedOverride=null){
    return smartMinimaxAllRefs(node, selectedOverride).map(ref => ({...ref, kind:mediaKindForItem(ref)}));
}
async function smartDirectorMaterializeTimelineRefs(node, seg){
    if(seg?.type !== 'connection'){
        delete seg.runtimeTimelineRefs;
        return [];
    }
    const derived = smartDirectorApplyConnectionDerivation(node, seg);
    if(!derived?.inputs?.length){
        throw new Error(capabilityUiText('连接 Clip 至少需要命中一侧普通 Clip','A connection Clip must touch at least one ordinary Clip'));
    }
    const refs = [];
    for(const input of derived?.inputs || []){
        const source = (node.segments || []).find(item => item.id === input.sourceClipId && item.type !== 'connection');
        const result = source?.result;
        if(!result?.url){
            const sourceIndex = Math.max(0, (node.segments || []).findIndex(item => item.id === input.sourceClipId));
            throw new Error(capabilityUiText(`连接 Clip 缺少来源：请先生成 Clip ${sourceIndex + 1}`,`Connection Clip source is missing: generate Clip ${sourceIndex + 1} first`));
        }
        const body = {source_url:result.url, operation:input.operation};
        if(input.operation === 'video_segment'){
            body.start_ms = Math.max(0, Math.round(Number(input.startMs || 0) - Number(source.startMs || 0)));
            body.end_ms = Math.max(body.start_ms + 1, Math.round(Number(input.endMs || 0) - Number(source.startMs || 0)));
        }
        const response = await fetch('/api/smart-canvas/director-reference', {
            method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)
        });
        if(!response.ok) throw new Error(await smartResponseErrorMessage(response, capabilityUiText('无法准备连接 Clip 的时间线输入','Failed to prepare timeline inputs for the connection Clip')));
        const materialized = await response.json();
        input.sourceResultId = String(result.id || result.resultId || result.url || '');
        input.referenceUrl = materialized.url || '';
        refs.push({
            ...materialized,
            url:materialized.url,
            name:input.side === 'left' ? capabilityUiText('上一 Clip 时间线输入','Previous Clip timeline input') : capabilityUiText('下一 Clip 时间线输入','Next Clip timeline input'),
            kind:materialized.kind || (input.operation === 'video_segment' ? 'video' : 'image'),
            role:input.operation === 'last_frame' ? 'first_frame' : input.operation === 'first_frame' ? 'last_frame' : 'reference_video',
            timelineLocked:true,
            sourceClipId:input.sourceClipId,
            sourceResultId:input.sourceResultId,
            operation:input.operation,
            side:input.side
        });
    }
    seg.runtimeTimelineRefs = refs;
    return refs;
}
function smartDirectorGenericRunSettings(node, seg, refs=[]){
    const generation = seg?.generation || {};
    const providerId = String(generation.providerId || '');
    const modelId = String(generation.model || '');
    if(!providerId || !modelId) throw new Error(capabilityUiText('请先选择通用导演台的平台和模型','Select a platform and model for the generic director first'));
    const profile = capabilityProfileFor(providerId, modelId, 'video_generation');
    if(!profile) throw new Error(capabilityUiText(`当前能力档案中没有视频模型 ${modelId}`,`Video model ${modelId} is missing from the capability catalog`));
    const params = generation.params && typeof generation.params === 'object' ? generation.params : {};
    const parameterSource = smartDirectorCapabilityParameterSource(seg, profile);
    const submittedParams = capabilityParameterSubmissionValues(profile, parameterSource);
    const ratioEntry = Object.entries(profile.parameters || {}).find(([key, spec]) => capabilityParameterSemantic(key, spec) === 'aspect_ratio');
    const durationEntry = Object.entries(profile.parameters || {}).find(([key, spec]) => capabilityParameterSemantic(key, spec) === 'duration');
    const ratio = String((ratioEntry ? submittedParams[ratioEntry[0]] : '') || seg?.aspectRatio || '16:9').match(/\d+\s*:\s*\d+/)?.[0]?.replace(/\s+/g, '') || '16:9';
    const duration = Number((durationEntry ? submittedParams[durationEntry[0]] : '') || seg?.duration || 5);
    return SMART_DIRECTOR_CORE.isolatedVideoRunSettings({
        providerId,
        familyId:String(profile.family_id || ''),
        modelId,
        mode:String(generation.mode || ''),
        params,
        submittedParams,
        duration:Number.isFinite(duration) ? duration : 5,
        aspectRatio:ratio,
        useFrameRoles:refs.filter(ref => ref.kind === 'image' && ['first_frame','last_frame'].includes(ref.role)).length > 0
    });
}
function smartDirectorValidatePrompt(node, seg){
    if(isMiniMaxDirectorNode(node)) return;
    const providerId = String(seg?.generation?.providerId || '');
    const modelId = String(seg?.generation?.model || '');
    const profile = capabilityProfileFor(providerId, modelId, 'video_generation');
    const state = smartDirectorPromptState(seg, profile);
    if(state.valid) return;
    if(state.tooLong){
        throw new Error(capabilityUiText(
            `模型 ${modelId} 的提示词当前 ${state.characters} 个字符，最多允许 ${state.maxChars} 个字符`,
            `The prompt for ${modelId} has ${state.characters} characters; the limit is ${state.maxChars}`
        ));
    }
    throw new Error(capabilityUiText('请输入当前 Clip 的提示词','Enter a prompt for this Clip'));
}
